<template><section aria-label="Past providers" class="past-providers"><h2>Past providers</h2><p>This record shows providers previously assigned to this service account. Earlier records remain available when services end or a new provider is assigned.</p><p v-if="loading" role="status">Loading past providers…</p><p v-if="error" role="alert">{{error}}</p><p v-if="!loading&&!providers.length&&!error">No past provider assignments are recorded here.</p><article v-for="provider in providers" :key="provider.id"><h3>{{provider.providerName||'Previously assigned provider'}}</h3><p>{{provider.label}} · {{provider.statusLabel}}</p><p v-if="provider.recordedAt">Service record created {{date(provider.recordedAt)}}<template v-if="provider.endedAt"> · Ended {{date(provider.endedAt)}}</template></p><p v-if="provider.reason">{{provider.reason}}</p><button v-if="Number(provider.providerUserId)>0&&Number(provider.serviceId)>0&&!provider.currentServiceActive" type="button" @click="selected=selected===provider.id?null:provider.id">{{selected===provider.id?'Close return request':'Ask to return to services'}}</button><ServiceReturnRequest v-if="selected===provider.id" :client-id="clientId" :service-id="Number(provider.serviceId)" :provider-name="provider.providerName" /></article><ReenrollmentPackages :client-id="clientId" /></section></template>
<script setup>
import {ref,watch,onUnmounted} from 'vue';
import {usePortalCareApi} from '../../composables/usePortalCareApi';
import ServiceReturnRequest from './ServiceReturnRequest.vue';
import ReenrollmentPackages from './ReenrollmentPackages.vue';
const props=defineProps({clientId:{type:Number,required:true}}),api=usePortalCareApi(),providers=ref([]),selected=ref(null),loading=ref(false),error=ref('');let generation=0;
const date=value=>new Date(typeof value==='string'&&!/(Z|[+-]\d\d:\d\d)$/.test(value)?value.replace(' ','T')+'Z':value).toLocaleDateString();
watch(()=>props.clientId,async()=>{const own=++generation;providers.value=[];selected.value=null;loading.value=true;error.value='';try{const {data}=await api.get(`/guardian-portal/clients/${props.clientId}/past-providers`,{skipGlobalLoading:true});if(own===generation)providers.value=data.providers||[];}catch(e){if(own===generation)error.value=e.response?.data?.error?.message||'Past provider records could not load.';}finally{if(own===generation)loading.value=false;}},{immediate:true});onUnmounted(()=>{generation++;});
</script>
<style scoped>.past-providers{padding:20px;background:white;border:1px solid #cedde2;border-radius:12px}.past-providers article{padding:16px 0;border-top:1px solid #dce6eb}.past-providers button{font:inherit;padding:10px;border:1px solid #8da8b4;border-radius:7px;background:white;cursor:pointer}.past-providers p{line-height:1.55}</style>
